//! marina runtime
//!
//! Linked (as a static library) into every compiled marina binary.
//! Provides:
//!   * Automatic Reference Counting (ARC) for heap objects (strings, promises)
//!   * A promise type used by compiled `async` functions
//!   * A multithreaded event loop: continuations scheduled on a worker pool,
//!     driven by promise resolution and timers (`setTimeout`).
//!
//! All exported functions have a stable C ABI; the LLVM IR generated by the
//! compiler calls into them directly.

use std::alloc::{alloc, dealloc, Layout};
use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap, VecDeque};
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::os::raw::c_void;
use std::sync::atomic::{AtomicBool, AtomicI64, Ordering};
use std::sync::{Condvar, Mutex, OnceLock};
use std::time::{Duration, Instant};

// ---------------------------------------------------------------------------
// Values
// ---------------------------------------------------------------------------

pub const TAG_VOID: i32 = 0;
pub const TAG_INT: i32 = 1;
pub const TAG_FLOAT: i32 = 2;
pub const TAG_STRING: i32 = 3;
pub const TAG_BOOL: i32 = 4;

/// Tagged value passed between compiled code and the runtime.
/// Must match the LLVM type `%mv = type { i32, i32, i64, double, ptr }`.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct MValue {
    pub tag: i32,
    pub pad: i32,
    pub i: i64,
    pub f: f64,
    pub p: *mut c_void,
}

unsafe impl Send for MValue {}

impl Default for MValue {
    fn default() -> Self {
        MValue { tag: TAG_VOID, pad: 0, i: 0, f: 0.0, p: std::ptr::null_mut() }
    }
}

// ---------------------------------------------------------------------------
// Reference counting (ARC)
// ---------------------------------------------------------------------------

const KIND_STRING: u8 = 0;
const KIND_PROMISE: u8 = 1;
const KIND_ARRAY: u8 = 2;
const KIND_OBJECT: u8 = 3;

/// Every ref-counted heap object starts with this header.
/// `rc < 0` means immortal (interned string literals — like Swift's literal
/// strings, `release` on them is a no-op).
#[repr(C)]
struct Header {
    rc: AtomicI64,
    kind: u8,
    _pad: [u8; 7],
}

#[repr(C)]
struct StrObj {
    h: Header,
    len: usize,
    // UTF-8 bytes follow the struct
}

const STR_HDR: usize = std::mem::size_of::<StrObj>();

unsafe fn str_data<'a>(p: *mut u8) -> &'a [u8] {
    let obj = p as *mut StrObj;
    let len = (*obj).len;
    std::slice::from_raw_parts(p.add(STR_HDR), len)
}

fn alloc_string(bytes: &[u8], rc: i64) -> *mut u8 {
    unsafe {
        let layout = Layout::from_size_align(STR_HDR + bytes.len(), 8).unwrap();
        let p = alloc(layout);
        let obj = p as *mut StrObj;
        (*obj).h = Header { rc: AtomicI64::new(rc), kind: KIND_STRING, _pad: [0; 7] };
        (*obj).len = bytes.len();
        std::ptr::copy_nonoverlapping(bytes.as_ptr(), p.add(STR_HDR), bytes.len());
        p
    }
}

unsafe fn retain_ptr(p: *mut u8) {
    let h = p as *mut Header;
    let rc = (*h).rc.load(Ordering::Relaxed);
    if rc < 0 {
        return; // immortal
    }
    (*h).rc.fetch_add(1, Ordering::Relaxed);
}

unsafe fn release_ptr(p: *mut u8) {
    let h = p as *mut Header;
    let rc = (*h).rc.load(Ordering::Relaxed);
    if rc < 0 {
        return; // immortal
    }
    if (*h).rc.fetch_sub(1, Ordering::AcqRel) == 1 {
        free_obj(p);
    }
}

unsafe fn free_obj(p: *mut u8) {
    let kind = (*(p as *mut Header)).kind;
    match kind {
        KIND_STRING => {
            let len = (*(p as *mut StrObj)).len;
            dealloc(p, Layout::from_size_align(STR_HDR + len, 8).unwrap());
        }
        KIND_PROMISE => {
            let pr = p as *mut Promise;
            let v = (*pr).inner.lock().unwrap().value;
            if v.tag == TAG_STRING && !v.p.is_null() {
                release_ptr(v.p as *mut u8);
            }
            dealloc(p as *mut u8, Layout::new::<Promise>());
        }
        KIND_ARRAY => {
            let arr = p as *mut ArrayObj;
            release_elements(&(*arr).data);
            dealloc(p as *mut u8, Layout::new::<ArrayObj>());
        }
        KIND_OBJECT => {
            let obj = p as *mut ObjectObj;
            release_elements(&(*obj).data);
            dealloc(p as *mut u8, Layout::new::<ObjectObj>());
        }
        _ => {}
    }
}

// Opaque malloc/free helpers for compiler-allocated memory (async frames,
// closure environments). The total size is stored in an 8-byte header so we
// can free without the caller remembering it.

unsafe fn c_alloc(size: usize) -> *mut u8 {
    let total = size + 8;
    let l = Layout::from_size_align(total, 8).unwrap();
    let p = alloc(l);
    (p as *mut usize).write(total);
    p.add(8)
}

unsafe fn c_free(p: *mut c_void) {
    if p.is_null() {
        return;
    }
    let q = (p as *mut u8).sub(8);
    let total = (q as *mut usize).read();
    dealloc(q, Layout::from_size_align(total, 8).unwrap());
}

// Interned string literals (immortal, created on first use).

fn literal_table() -> &'static Mutex<HashMap<Vec<u8>, usize>> {
    static T: OnceLock<Mutex<HashMap<Vec<u8>, usize>>> = OnceLock::new();
    T.get_or_init(|| Mutex::new(HashMap::new()))
}

// ---------------------------------------------------------------------------
// Promises
// ---------------------------------------------------------------------------

type ResumeFn = extern "C" fn(frame: *mut c_void, state: i32, value: *const MValue);

struct Waiter {
    resume: ResumeFn,
    frame: *mut c_void,
    state: i32,
}
unsafe impl Send for Waiter {}

#[repr(C)]
struct Promise {
    h: Header,
    inner: Mutex<PromiseInner>,
}

struct PromiseInner {
    done: bool,
    value: MValue,
    waiters: Vec<Waiter>,
}

/// A scheduled continuation: runs `resume(frame, state, &value)` on a worker
/// thread, then drops the promise reference it owns.
struct WaiterTask {
    promise: *mut Promise,
    waiter: Waiter,
    value: MValue,
}
unsafe impl Send for WaiterTask {}

fn run_waiter(t: WaiterTask) {
    (t.waiter.resume)(t.waiter.frame, t.waiter.state, &t.value);
    unsafe { release_ptr(t.promise as *mut u8) };
}

// ---------------------------------------------------------------------------
// Event loop state (shared by workers, the timer thread and the main thread)
// ---------------------------------------------------------------------------

type CFn0 = extern "C" fn(*mut c_void);

struct TimerJob {
    f: CFn0,
    env: *mut c_void,
    drop_fn: CFn0,
}
unsafe impl Send for TimerJob {}

struct TimerEntry {
    due: Instant,
    seq: u64,
    job: TimerJob,
}

impl PartialEq for TimerEntry {
    fn eq(&self, other: &Self) -> bool {
        self.seq == other.seq
    }
}
impl Eq for TimerEntry {}
impl PartialOrd for TimerEntry {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for TimerEntry {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        (self.due, self.seq).cmp(&(other.due, other.seq))
    }
}

type Task = Box<dyn FnOnce() + Send>;

struct Rt {
    tasks: VecDeque<Task>,
    running: usize,
    timers: BinaryHeap<Reverse<TimerEntry>>,
    seq: u64,
    /// Promises created but not yet resolved. The event loop keeps running
    /// while this is non-zero.
    pending_promises: usize,
    /// HTTP servers that are still listening — the program never exits
    /// while one is up (stop with Ctrl-C).
    pending_listeners: usize,
}

fn rt() -> &'static (Mutex<Rt>, Condvar) {
    static RT: OnceLock<(Mutex<Rt>, Condvar)> = OnceLock::new();
    RT.get_or_init(|| {
        (
            Mutex::new(Rt {
                tasks: VecDeque::new(),
                running: 0,
                timers: BinaryHeap::new(),
                seq: 0,
                pending_promises: 0,
                pending_listeners: 0,
            }),
            Condvar::new(),
        )
    })
}

fn quiescent(g: &Rt) -> bool {
    g.tasks.is_empty()
        && g.running == 0
        && g.timers.is_empty()
        && g.pending_promises == 0
        && g.pending_listeners == 0
}

fn worker_loop() {
    let (m, cv) = rt();
    loop {
        let task = {
            let mut g = m.lock().unwrap();
            loop {
                if let Some(t) = g.tasks.pop_front() {
                    g.running += 1;
                    break t;
                }
                g = cv.wait(g).unwrap();
            }
        };
        task();
        let mut g = m.lock().unwrap();
        g.running -= 1;
        cv.notify_all();
    }
}

fn timer_loop() {
    let (m, cv) = rt();
    let mut g = m.lock().unwrap();
    loop {
        let next = g.timers.peek().map(|Reverse(e)| e.due);
        match next {
            Some(due) => {
                let now = Instant::now();
                if now >= due {
                    // Pop the timer and schedule its callback as a task in the
                    // same critical section so the loop is never momentarily
                    // "quiescent".
                    let Reverse(entry) = g.timers.pop().unwrap();
                    let job: TimerJob = entry.job;
                    g.tasks
                        .push_back(Box::new(move || {
                            let j: TimerJob = job;
                            (j.f)(j.env);
                            (j.drop_fn)(j.env);
                        }));
                    cv.notify_all();
                    continue;
                } else {
                    let (ng, _) = cv.wait_timeout(g, due - now).unwrap();
                    g = ng;
                }
            }
            None => {
                g = cv.wait(g).unwrap();
            }
        }
    }
}

// ---------------------------------------------------------------------------
// C ABI exported to compiled code
// ---------------------------------------------------------------------------

#[no_mangle]
pub extern "C" fn marina_event_loop_start() {
    static STARTED: AtomicBool = AtomicBool::new(false);
    if STARTED.swap(true, Ordering::SeqCst) {
        return;
    }
    let n = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1)
        .clamp(1, 8);
    for _ in 0..n {
        std::thread::spawn(worker_loop);
    }
    std::thread::spawn(timer_loop);
}

#[no_mangle]
pub extern "C" fn marina_event_loop_run() -> i32 {
    let (m, cv) = rt();
    let mut g = m.lock().unwrap();
    while !quiescent(&g) {
        g = cv.wait(g).unwrap();
    }
    0
}

/// Allocate an async-function frame (opaque to the runtime; the compiler
/// emits its own drop code before calling marina_frame_free).
#[no_mangle]
pub extern "C" fn marina_frame_alloc(size: i64) -> *mut c_void {
    unsafe { c_alloc(size.max(0) as usize) as *mut c_void }
}

#[no_mangle]
pub extern "C" fn marina_frame_free(p: *mut c_void) {
    unsafe { c_free(p) }
}

/// Allocate a closure environment (contents owned by the compiler; a
/// compiler-generated `drop` function releases captured refs and calls
/// marina_closure_free).
#[no_mangle]
pub extern "C" fn marina_closure_alloc(size: i64) -> *mut c_void {
    unsafe { c_alloc(size.max(0) as usize) as *mut c_void }
}

#[no_mangle]
pub extern "C" fn marina_closure_free(p: *mut c_void) {
    unsafe { c_free(p) }
}

#[no_mangle]
pub extern "C" fn marina_retain(p: *mut c_void) -> *mut c_void {
    unsafe { retain_ptr(p as *mut u8) };
    p
}

#[no_mangle]
pub extern "C" fn marina_release(p: *mut c_void) {
    unsafe { release_ptr(p as *mut u8) };
}

/// Create a promise with refcount 1. Registers it in `pending_promises` so
/// the event loop waits for it to resolve.
#[no_mangle]
pub extern "C" fn marina_promise_create() -> *mut c_void {
    let p = unsafe {
        let p = alloc(Layout::new::<Promise>()) as *mut Promise;
        (*p).h = Header { rc: AtomicI64::new(1), kind: KIND_PROMISE, _pad: [0; 7] };
        (*p).inner = Mutex::new(PromiseInner {
            done: false,
            value: MValue::default(),
            waiters: Vec::new(),
        });
        p
    };
    let (m, _) = rt();
    m.lock().unwrap().pending_promises += 1;
    p as *mut c_void
}

/// Run a promise executor synchronously (JS semantics), then drop the
/// executor environment, then hand the caller a +1 reference.
#[no_mangle]
pub extern "C" fn marina_promise_run_executor(
    promise: *mut c_void,
    executor: *const c_void,
    env: *mut c_void,
    env_drop: *const c_void,
) -> *mut c_void {
    let f: CFn0 = unsafe { std::mem::transmute(executor) };
    let d: CFn0 = unsafe { std::mem::transmute(env_drop) };
    f(env);
    d(env);
    unsafe { retain_ptr(promise as *mut u8) };
    promise
}

/// Resolve a promise. First resolve wins; waiters are scheduled as tasks on
/// the event loop (worker threads).
#[no_mangle]
pub extern "C" fn marina_promise_resolve(promise: *mut c_void, value: *const MValue) {
    unsafe {
        let p = promise as *mut Promise;
        let waiters: Vec<Waiter>;
        {
            let mut inner = (*p).inner.lock().unwrap();
            if inner.done {
                return;
            }
            let v = *value;
            if v.tag == TAG_STRING && !v.p.is_null() {
                retain_ptr(v.p as *mut u8);
            }
            inner.value = v;
            inner.done = true;
            waiters = std::mem::take(&mut inner.waiters);
        }
        let value = (*p).inner.lock().unwrap().value;
        let (m, cv) = rt();
        let mut g = m.lock().unwrap();
        for w in waiters {
            retain_ptr(promise as *mut u8); // task owns this ref
            let t = WaiterTask { promise: p, waiter: w, value };
            g.tasks.push_back(Box::new(move || run_waiter(t)));
        }
        g.pending_promises -= 1;
        cv.notify_all();
    }
}

/// Suspend the current async function until `promise` resolves.
/// Consumes the caller's reference to the promise.
/// On resume, the runtime calls `resume(frame, state, &value)`.
#[no_mangle]
pub extern "C" fn marina_await(
    promise: *mut c_void,
    resume: *const c_void,
    frame: *mut c_void,
    state: i32,
) {
    unsafe {
        let p = promise as *mut Promise;
        let f: ResumeFn = std::mem::transmute(resume);
        let done_value;
        {
            let mut inner = (*p).inner.lock().unwrap();
            if inner.done {
                done_value = Some(inner.value);
            } else {
                inner.waiters.push(Waiter { resume: f, frame, state });
                return;
            }
        }
        if let Some(value) = done_value {
            let t = WaiterTask {
                promise: p,
                waiter: Waiter { resume: f, frame, state },
                value,
            };
            let (m, cv) = rt();
            let mut g = m.lock().unwrap();
            g.tasks.push_back(Box::new(move || run_waiter(t)));
            cv.notify_all();
        }
    }
}

/// setTimeout(callback, ms): the callback runs on a worker thread after `ms`.
#[no_mangle]
pub extern "C" fn marina_set_timeout(
    f: *const c_void,
    env: *mut c_void,
    env_drop: *const c_void,
    ms: i64,
) {
    let f: CFn0 = unsafe { std::mem::transmute(f) };
    let d: CFn0 = unsafe { std::mem::transmute(env_drop) };
    let (m, cv) = rt();
    let mut g = m.lock().unwrap();
    let seq = g.seq + 1;
    g.seq = seq;
    g.timers.push(Reverse(TimerEntry {
        due: Instant::now() + Duration::from_millis(ms.max(0) as u64),
        seq,
        job: TimerJob { f, env, drop_fn: d },
    }));
    cv.notify_all();
}

/// Return an owned reference to the interned literal `bytes`.
#[no_mangle]
pub extern "C" fn marina_string_literal(bytes: *const u8, len: i64) -> *mut c_void {
    let slice = unsafe { std::slice::from_raw_parts(bytes, len.max(0) as usize) };
    let mut map = literal_table().lock().unwrap();
    if let Some(&p) = map.get(slice) {
        return p as *mut c_void;
    }
    let p = alloc_string(slice, -1); // immortal
    map.insert(slice.to_vec(), p as usize);
    p as *mut c_void
}

/// Concatenate two strings (borrowed) into a new owned string.
#[no_mangle]
pub extern "C" fn marina_string_concat(a: *const c_void, b: *const c_void) -> *mut c_void {
    unsafe {
        let (a, b) = (a as *mut u8, b as *mut u8);
        let da = str_data(a);
        let db = str_data(b);
        let mut out = Vec::with_capacity(da.len() + db.len());
        out.extend_from_slice(da);
        out.extend_from_slice(db);
        alloc_string(&out, 1) as *mut c_void
    }
}

/// Length of a string in bytes (borrowed).
#[no_mangle]
pub extern "C" fn marina_string_len(s: *const c_void) -> i64 {
    unsafe { str_data(s as *mut u8).len() as i64 }
}

fn value_to_string(v: &MValue) -> String {
    match v.tag {
        TAG_STRING => unsafe { String::from_utf8_lossy(str_data(v.p as *mut u8)).into_owned() },
        TAG_INT => format!("{}", v.i as i32),
        TAG_FLOAT => fmt_float(v.f),
        TAG_BOOL => if v.i != 0 { "true".into() } else { "false".into() },
        TAG_STREAM => format!("[stream {}]", v.i),
        TAG_ARRAY => {
            let arr = unsafe { &*(v.p as *mut ArrayObj) };
            let parts: Vec<String> = arr.data.iter().map(value_to_string).collect();
            format!("[{}]", parts.join(", "))
        }
        TAG_OBJECT => {
            let obj = unsafe { &*(v.p as *mut ObjectObj) };
            let reg = class_table().lock().unwrap();
            match reg.get(&obj.class_id) {
                Some(ci) => {
                    let parts: Vec<String> = obj
                        .data
                        .iter()
                        .enumerate()
                        .map(|(i, f)| {
                            let name = ci.fields.get(i).map(|s| s.as_str()).unwrap_or("?");
                            format!("{}: {}", name, value_to_string(f))
                        })
                        .collect();
                    format!("{} {{ {} }}", ci.name, parts.join(", "))
                }
                None => "{...}".into(),
            }
        }
        _ => "undefined".into(),
    }
}

fn fmt_float(f: f64) -> String {
    if f.is_finite() && f == f.trunc() && f.abs() < 1e15 {
        format!("{}", f as i64)
    } else {
        format!("{}", f)
    }
}

/// Convert a value to a new owned string reference.
#[no_mangle]
pub extern "C" fn marina_to_string(v: *const MValue) -> *mut c_void {
    unsafe {
        match (*v).tag {
            TAG_STRING => {
                let p = (*v).p as *mut u8;
                if !p.is_null() {
                    let rc = (*(p as *mut Header)).rc.load(Ordering::Relaxed);
                    if rc >= 0 {
                        retain_ptr(p);
                    }
                    return p as *mut c_void;
                }
                alloc_string(b"", 1) as *mut c_void
            }
            _ => alloc_string(value_to_string(&*v).as_bytes(), 1) as *mut c_void,
        }
    }
}

// ---------------------------------------------------------------------------
// Arrays
// ---------------------------------------------------------------------------
//
// A marina array is a ref-counted heap object holding a growable vector of
// tagged MValues. Element ownership follows the ARC rules: the array retains
// string elements when they are inserted, and retains them again into the out
// MValue when they are read out (the caller owns that reference). Every
// MValue crossing the C ABI is borrowed; a callee that keeps it retains it.

pub const TAG_ARRAY: i32 = 5;

#[repr(C)]
struct ArrayObj {
    h: Header,
    tag: i32,
    data: Vec<MValue>,
}

unsafe fn as_array<'a>(p: *mut c_void) -> &'a mut ArrayObj {
    &mut *(p as *mut ArrayObj)
}

/// Value used for callbacks: `fn(env, item, out)` (map/filter), with
/// `out` omitted for forEach and an extra `acc` for reduce.
type ArrayCb2 = extern "C" fn(env: *mut c_void, item: *const MValue, out: *mut MValue);
type ArrayCb1 = extern "C" fn(env: *mut c_void, item: *const MValue);
type ArrayCb3 =
    extern "C" fn(env: *mut c_void, acc: *const MValue, item: *const MValue, out: *mut MValue);

fn mv_from(tag: i32, v: &MValue) -> MValue {
    let mut m = *v;
    m.tag = tag;
    m.pad = 0;
    m
}

/// Retain the payload of an MValue if the callee takes ownership of it.
unsafe fn retain_payload(v: &MValue) {
    if is_ptr_tag(v.tag) && !v.p.is_null() {
        let rc = (*(v.p as *mut Header)).rc.load(Ordering::Relaxed);
        if rc >= 0 {
            retain_ptr(v.p as *mut u8);
        }
    }
}

fn array_get_checked(a: *mut c_void, i: i64) -> MValue {
    unsafe {
        let arr = as_array(a);
        let len = arr.data.len() as i64;
        if i < 0 || i >= len {
            eprintln!(
                "marina runtime panic: array index {} out of bounds (length {})",
                i, len
            );
            std::process::exit(101);
        }
        let v = arr.data[i as usize];
        retain_payload(&v);
        v
    }
}

fn release_elements(vals: &[MValue]) {
    for v in vals {
        if is_ptr_tag(v.tag) && !v.p.is_null() {
            unsafe { release_ptr(v.p as *mut u8) };
        }
    }
}

/// Tags whose payload is an ARC-managed heap pointer.
fn is_ptr_tag(tag: i32) -> bool {
    tag == TAG_STRING || tag == TAG_ARRAY || tag == TAG_OBJECT
}

#[no_mangle]
pub extern "C" fn marina_array_new(tag: i32) -> *mut c_void {
    let p = unsafe {
        let p = alloc(Layout::new::<ArrayObj>()) as *mut ArrayObj;
        (*p).h = Header { rc: AtomicI64::new(1), kind: KIND_ARRAY, _pad: [0; 7] };
        (*p).tag = tag;
        (*p).data = Vec::new();
        p
    };
    p as *mut c_void
}

#[no_mangle]
pub extern "C" fn marina_array_len(a: *mut c_void) -> i64 {
    unsafe { as_array(a).data.len() as i64 }
}

#[no_mangle]
pub extern "C" fn marina_array_push(a: *mut c_void, v: *const MValue) -> i64 {
    unsafe {
        let arr = as_array(a);
        retain_payload(&*v);
        arr.data.push(mv_from(arr.tag, &*v));
        arr.data.len() as i64
    }
}

#[no_mangle]
pub extern "C" fn marina_array_pop(a: *mut c_void, out: *mut MValue) {
    unsafe {
        let arr = as_array(a);
        match arr.data.pop() {
            Some(v) => {
                retain_payload(&v);
                *out = v;
            }
            None => {
                eprintln!("marina runtime panic: pop from an empty array");
                std::process::exit(101);
            }
        }
    }
}

#[no_mangle]
pub extern "C" fn marina_array_shift(a: *mut c_void, out: *mut MValue) {
    unsafe {
        let arr = as_array(a);
        if arr.data.is_empty() {
            eprintln!("marina runtime panic: shift from an empty array");
            std::process::exit(101);
        }
        let v = arr.data.remove(0);
        retain_payload(&v);
        *out = v;
    }
}

#[no_mangle]
pub extern "C" fn marina_array_unshift(a: *mut c_void, v: *const MValue) -> i64 {
    unsafe {
        let arr = as_array(a);
        retain_payload(&*v);
        arr.data.insert(0, mv_from(arr.tag, &*v));
        arr.data.len() as i64
    }
}

#[no_mangle]
pub extern "C" fn marina_array_get(a: *mut c_void, i: i64, out: *mut MValue) {
    let v = array_get_checked(a, i);
    unsafe { *out = v };
}

#[no_mangle]
pub extern "C" fn marina_array_set(a: *mut c_void, i: i64, v: *const MValue) {
    unsafe {
        let arr = as_array(a);
        let len = arr.data.len() as i64;
        if i < 0 || i >= len {
            eprintln!(
                "marina runtime panic: array index {} out of bounds (length {})",
                i, len
            );
            std::process::exit(101);
        }
        let nv = mv_from(arr.tag, &*v);
        retain_payload(&nv);
        let old = std::mem::replace(&mut arr.data[i as usize], nv);
        if is_ptr_tag(old.tag) && !old.p.is_null() {
            release_ptr(old.p as *mut u8);
        }
    }
}

#[no_mangle]
pub extern "C" fn marina_array_splice(a: *mut c_void, start: i64, count: i64) -> *mut c_void {
    unsafe {
        let arr = as_array(a);
        let len = arr.data.len() as i64;
        let start = start.clamp(0, len) as usize;
        let end = (start as i64 + count.clamp(0, len)).min(len) as usize;
        let removed: Vec<MValue> = arr.data.drain(start..end).collect();
        let out = marina_array_new(arr.tag) as *mut ArrayObj;
        (*out).data = removed;
        out as *mut c_void
    }
}

#[no_mangle]
pub extern "C" fn marina_array_slice(a: *mut c_void, start: i64, end: i64) -> *mut c_void {
    unsafe {
        let arr = as_array(a);
        let len = arr.data.len() as i64;
        let s = start.clamp(0, len) as usize;
        let e = end.clamp(0, len) as usize;
        let (s, e) = if s > e { (e, s) } else { (s, e) };
        let out = marina_array_new(arr.tag) as *mut ArrayObj;
        for v in &arr.data[s..e] {
            retain_payload(v);
            (*out).data.push(*v);
        }
        out as *mut c_void
    }
}

#[no_mangle]
pub extern "C" fn marina_array_concat(a: *mut c_void, b: *mut c_void) -> *mut c_void {
    unsafe {
        let out = marina_array_new(as_array(a).tag) as *mut ArrayObj;
        for src in [a, b] {
            for v in &as_array(src).data {
                retain_payload(v);
                (*out).data.push(*v);
            }
        }
        out as *mut c_void
    }
}

#[no_mangle]
pub extern "C" fn marina_array_reverse(a: *mut c_void) -> *mut c_void {
    unsafe {
        as_array(a).data.reverse();
        retain_ptr(a as *mut u8);
        a
    }
}

fn mv_cmp(x: &MValue, y: &MValue) -> std::cmp::Ordering {
    match (x.tag, y.tag) {
        (TAG_STRING, TAG_STRING) => unsafe {
            str_data(x.p as *mut u8).cmp(str_data(y.p as *mut u8))
        },
        _ => {
            let fx = if x.tag == TAG_FLOAT { x.f } else { x.i as f64 };
            let fy = if y.tag == TAG_FLOAT { y.f } else { y.i as f64 };
            fx.partial_cmp(&fy).unwrap_or(std::cmp::Ordering::Equal)
        }
    }
}

#[no_mangle]
pub extern "C" fn marina_array_sort(a: *mut c_void) -> *mut c_void {
    unsafe {
        as_array(a).data.sort_by(mv_cmp);
        retain_ptr(a as *mut u8);
        a
    }
}

#[no_mangle]
pub extern "C" fn marina_array_join(a: *mut c_void, sep: *const c_void) -> *mut c_void {
    unsafe {
        let arr = as_array(a);
        let sep_s = str_data(sep as *mut u8);
        let mut out = String::new();
        for (i, v) in arr.data.iter().enumerate() {
            if i > 0 {
                out.push_str(&String::from_utf8_lossy(sep_s));
            }
            out.push_str(&value_to_string(v));
        }
        alloc_string(out.as_bytes(), 1) as *mut c_void
    }
}

// --- higher-order methods (callbacks run synchronously on the caller) ---

#[no_mangle]
pub extern "C" fn marina_array_foreach(
    a: *mut c_void,
    cb: *const c_void,
    env: *mut c_void,
    env_drop: *const c_void,
) {
    unsafe {
        let f: ArrayCb1 = std::mem::transmute(cb);
        let d: CFn0 = std::mem::transmute(env_drop);
        for v in &as_array(a).data.clone() {
            retain_payload(v);
            f(env, v);
        }
        d(env);
    }
}

#[no_mangle]
pub extern "C" fn marina_array_map(
    a: *mut c_void,
    cb: *const c_void,
    env: *mut c_void,
    env_drop: *const c_void,
    out_tag: i32,
) -> *mut c_void {
    unsafe {
        let f: ArrayCb2 = std::mem::transmute(cb);
        let d: CFn0 = std::mem::transmute(env_drop);
        let out = marina_array_new(out_tag) as *mut ArrayObj;
        for v in &as_array(a).data.clone() {
            retain_payload(v);
            let mut res = MValue::default();
            f(env, v, &mut res);
            retain_payload(&res);
            (*out).data.push(mv_from(out_tag, &res));
        }
        d(env);
        out as *mut c_void
    }
}

#[no_mangle]
pub extern "C" fn marina_array_filter(
    a: *mut c_void,
    cb: *const c_void,
    env: *mut c_void,
    env_drop: *const c_void,
) -> *mut c_void {
    unsafe {
        let f: ArrayCb2 = std::mem::transmute(cb);
        let d: CFn0 = std::mem::transmute(env_drop);
        let out = marina_array_new(as_array(a).tag) as *mut ArrayObj;
        for v in &as_array(a).data.clone() {
            retain_payload(v);
            let mut res = MValue::default();
            f(env, v, &mut res);
            if res.tag == TAG_BOOL && res.i != 0 {
                retain_payload(v);
                (*out).data.push(*v);
            }
        }
        d(env);
        out as *mut c_void
    }
}

#[no_mangle]
pub extern "C" fn marina_array_reduce(
    a: *mut c_void,
    cb: *const c_void,
    env: *mut c_void,
    env_drop: *const c_void,
    init: *const MValue,
    out: *mut MValue,
) {
    unsafe {
        let f: ArrayCb3 = std::mem::transmute(cb);
        let d: CFn0 = std::mem::transmute(env_drop);
        let mut acc = *init;
        retain_payload(&acc);
        for v in &as_array(a).data.clone() {
            retain_payload(v);
            let mut res = MValue::default();
            f(env, &acc, v, &mut res);
            retain_payload(&res);
            // release the previous accumulator's payload
            if is_ptr_tag(acc.tag) && !acc.p.is_null() {
                release_ptr(acc.p as *mut u8);
            }
            acc = res;
        }
        retain_payload(&acc);
        *out = acc;
        d(env);
    }
}

// ---------------------------------------------------------------------------
// Objects & ghost classes
// ---------------------------------------------------------------------------

pub const TAG_OBJECT: i32 = 6;

/// Struct-of-fields object: one MValue slot per class field, addressed by
/// field index. Field names/classes are registered by the generated program.
#[repr(C)]
struct ObjectObj {
    h: Header,
    class_id: i32,
    data: Vec<MValue>,
}

unsafe fn as_object<'a>(p: *mut c_void) -> &'a mut ObjectObj {
    &mut *(p as *mut ObjectObj)
}

struct ClassInfo {
    name: String,
    fields: Vec<String>,
}

fn class_table() -> &'static Mutex<HashMap<i32, ClassInfo>> {
    static T: OnceLock<Mutex<HashMap<i32, ClassInfo>>> = OnceLock::new();
    T.get_or_init(|| Mutex::new(HashMap::new()))
}

/// Register class metadata. `meta` points to `len` raw bytes of the form
/// "Name\0field1\0field2\0" (compiler-emitted global constant).
#[no_mangle]
pub extern "C" fn marina_class_register(class_id: i32, meta: *const c_void, len: i64) {
    let bytes =
        unsafe { std::slice::from_raw_parts(meta as *const u8, len.max(0) as usize) }.to_vec();
    let mut parts = bytes.split(|&b| b == 0).filter(|s| !s.is_empty());
    let name = String::from_utf8_lossy(parts.next().unwrap_or(&b"?"[..])).into_owned();
    let fields: Vec<String> = parts
        .map(|f| String::from_utf8_lossy(f).into_owned())
        .collect();
    class_table()
        .lock()
        .unwrap()
        .insert(class_id, ClassInfo { name, fields });
}

#[no_mangle]
pub extern "C" fn marina_object_new(class_id: i32, n_fields: i64) -> *mut c_void {
    unsafe {
        let p = alloc(Layout::new::<ObjectObj>()) as *mut ObjectObj;
        (*p).h = Header { rc: AtomicI64::new(1), kind: KIND_OBJECT, _pad: [0; 7] };
        (*p).class_id = class_id;
        (*p).data = vec![MValue::default(); n_fields.max(0) as usize];
        p as *mut c_void
    }
}

/// Object field read: bounds-checked, retains the payload into `out`
/// (the caller owns the reference).
#[no_mangle]
pub extern "C" fn marina_object_get(o: *mut c_void, i: i64, out: *mut MValue) {
    unsafe {
        let obj = as_object(o);
        let len = obj.data.len() as i64;
        if i < 0 || i >= len {
            eprintln!(
                "marina runtime panic: field index {} out of bounds (class has {} fields)",
                i, len
            );
            std::process::exit(101);
        }
        let v = obj.data[i as usize];
        retain_payload(&v);
        *out = v;
    }
}

/// Object field write: retains the new payload, releases the old one.
#[no_mangle]
pub extern "C" fn marina_object_set(o: *mut c_void, i: i64, v: *const MValue) {
    unsafe {
        let obj = as_object(o);
        let len = obj.data.len() as i64;
        if i < 0 || i >= len {
            eprintln!(
                "marina runtime panic: field index {} out of bounds (class has {} fields)",
                i, len
            );
            std::process::exit(101);
        }
        retain_payload(&*v);
        // store the MValue as-is: codegen builds it with the field's tag
        let new_v = *v;
        let old = std::mem::replace(&mut obj.data[i as usize], new_v);
        if is_ptr_tag(old.tag) && !old.p.is_null() {
            release_ptr(old.p as *mut u8);
        }
    }
}

/// console.log
#[no_mangle]
pub extern "C" fn marina_print(v: *const MValue) {
    unsafe { println!("{}", value_to_string(&*v)) }
}

// ---------------------------------------------------------------------------
// std module: net (TCP streams)
// ---------------------------------------------------------------------------

/// Stream handles live in a runtime table (not ARC-managed): a stream value
/// is just an id. `stream.close()` removes it; unclosed streams are closed
/// when the process exits.
pub const TAG_STREAM: i32 = 7;

type Streams = (HashMap<i64, TcpStream>, i64);

fn streams() -> &'static Mutex<Streams> {
    static T: OnceLock<Mutex<Streams>> = OnceLock::new();
    T.get_or_init(|| Mutex::new((HashMap::new(), 1)))
}

fn rt_panic(msg: String) -> ! {
    eprintln!("marina runtime panic: {}", msg);
    std::process::exit(101);
}

fn mv_to_string(v: &MValue) -> String {
    if v.tag == TAG_STRING {
        unsafe { String::from_utf8_lossy(str_data(v.p as *mut u8)).into_owned() }
    } else {
        value_to_string(v)
    }
}

fn out_mv(out: *mut MValue, v: MValue) {
    unsafe { *out = v };
}

fn mv_int(i: i64) -> MValue {
    MValue { tag: TAG_INT, pad: 0, i, f: 0.0, p: std::ptr::null_mut() }
}

fn mv_str_owned(s: String) -> MValue {
    let p = alloc_string(s.as_bytes(), 1);
    MValue { tag: TAG_STRING, pad: 0, i: 0, f: 0.0, p: p as *mut c_void }
}

unsafe fn drop_mv(v: &MValue) {
    if is_ptr_tag(v.tag) && !v.p.is_null() {
        release_ptr(v.p as *mut u8);
    }
}

fn stream_get(id: i64) -> TcpStream {
    let mut g = streams().lock().unwrap();
    match g.0.get_mut(&id) {
        Some(s) => match s.try_clone() {
            Ok(c) => c,
            Err(e) => rt_panic(format!("stream {}: {}", id, e)),
        },
        None => rt_panic(format!("invalid stream handle {}", id)),
    }
}

/// `net.connect(host, port)` — opens a TCP connection (30s read timeout).
#[no_mangle]
pub extern "C" fn marina_net_connect(host: *const MValue, port: *const MValue, out: *mut MValue) {
    let host_s = unsafe { mv_to_string(&*host) };
    let port_n = unsafe { (*port).i };
    match TcpStream::connect((host_s.as_str(), port_n as u16)) {
        Ok(s) => {
            let _ = s.set_read_timeout(Some(Duration::from_secs(30)));
            let mut g = streams().lock().unwrap();
            let id = g.1;
            g.1 += 1;
            g.0.insert(id, s);
            out_mv(out, MValue { tag: TAG_STREAM, pad: 0, i: id, f: 0.0, p: std::ptr::null_mut() });
        }
        Err(e) => rt_panic(format!("cannot connect to {}:{} ({})", host_s, port_n, e)),
    }
}

/// `stream.write(data)` — send bytes (borrowed string).
#[no_mangle]
pub extern "C" fn marina_net_write(s: *const MValue, data: *const MValue) {
    let id = unsafe { (*s).i };
    let bytes = unsafe { mv_to_string(&*data).into_bytes() };
    let mut st = stream_get(id);
    if let Err(e) = st.write_all(&bytes) {
        rt_panic(format!("stream {}: write failed ({})", id, e));
    }
}

/// `stream.read_all()` — read until EOF into an owned string.
#[no_mangle]
pub extern "C" fn marina_net_read_all(s: *const MValue, out: *mut MValue) {
    let id = unsafe { (*s).i };
    let mut st = stream_get(id);
    let mut buf = Vec::new();
    if let Err(e) = st.read_to_end(&mut buf) {
        rt_panic(format!("stream {}: read failed ({})", id, e));
    }
    out_mv(out, mv_str_owned(String::from_utf8_lossy(&buf).into_owned()));
}

/// `stream.close()`
#[no_mangle]
pub extern "C" fn marina_net_close(s: *const MValue) {
    let id = unsafe { (*s).i };
    streams().lock().unwrap().0.remove(&id);
}

/// `str == str` / `str != str` — content comparison over two string MValues.
#[no_mangle]
pub extern "C" fn marina_str_eq(a: *const MValue, b: *const MValue) -> bool {
    unsafe { mv_to_string(&*a) == mv_to_string(&*b) }
}

// ---------------------------------------------------------------------------
// std module: http (client + server), built on net
// ---------------------------------------------------------------------------

type ListenCb = extern "C" fn(env: *mut c_void, req: *const MValue, res: *const MValue);

/// Sockets backing `res` objects of in-flight handler invocations.
fn res_sockets() -> &'static Mutex<HashMap<usize, TcpStream>> {
    static T: OnceLock<Mutex<HashMap<usize, TcpStream>>> = OnceLock::new();
    T.get_or_init(|| Mutex::new(HashMap::new()))
}

fn http_parse_url(url: &str) -> (String, u16, String) {
    let rest = match url.strip_prefix("http://") {
        Some(r) => r,
        None => rt_panic(format!(
            "http: only http:// URLs are supported (https is not available yet), got '{}'",
            url
        )),
    };
    let (hostport, path) = match rest.find('/') {
        Some(i) => (&rest[..i], rest[i..].to_string()),
        None => (rest, "/".to_string()),
    };
    let (host, port) = match hostport.rsplit_once(':') {
        Some((h, p)) => match p.parse::<u16>() {
            Ok(n) => (h.to_string(), n),
            Err(_) => rt_panic(format!("http: invalid port in url '{}'", url)),
        },
        None => (hostport.to_string(), 80),
    };
    if host.is_empty() {
        rt_panic(format!("http: missing host in url '{}'", url));
    }
    (host, port, path)
}

/// Perform a request using the net std module (connect → write → read_all →
/// close), then parse the response into (status, body).
fn http_do_request(method: &str, url: &str, body: Option<String>) -> (i64, String) {
    let (host, port, path) = http_parse_url(url);
    let mut req = format!(
        "{} {} HTTP/1.1\r\nHost: {}\r\nUser-Agent: marina-http/0.2\r\nConnection: close\r\n",
        method, path, host
    );
    match &body {
        Some(b) => {
            req.push_str(&format!(
                "Content-Type: text/plain\r\nContent-Length: {}\r\n\r\n{}",
                b.len(),
                b
            ));
        }
        None => req.push_str("Content-Length: 0\r\n\r\n"),
    }

    let host_mv = mv_str_owned(host.clone());
    let port_mv = mv_int(port as i64);
    let mut st_mv = MValue::default();
    marina_net_connect(&host_mv, &port_mv, &mut st_mv);
    unsafe { drop_mv(&host_mv) };
    let req_mv = mv_str_owned(req);
    marina_net_write(&st_mv, &req_mv);
    unsafe { drop_mv(&req_mv) };
    let mut resp_mv = MValue::default();
    marina_net_read_all(&st_mv, &mut resp_mv);
    marina_net_close(&st_mv);
    let resp = mv_to_string(&resp_mv);
    unsafe { drop_mv(&resp_mv) };

    let (head, body_s) = match resp.find("\r\n\r\n") {
        Some(i) => (resp[..i].to_string(), resp[i + 4..].to_string()),
        None => (resp, String::new()),
    };
    let status = head
        .split_whitespace()
        .nth(1)
        .and_then(|s| s.parse::<i64>().ok())
        .unwrap_or(0);
    (status, body_s)
}

fn set_object_field(o: *mut c_void, i: i64, v: MValue) {
    // object_set retains the payload; drop our own reference after storing
    marina_object_set(o, i, &v);
    unsafe { drop_mv(&v) };
}

/// `http.get(url)` / `http.post(url, body)` — returns an `http_Response`
/// object `{ status, body }`.
#[no_mangle]
pub extern "C" fn marina_http_request(
    method: *const MValue,
    url: *const MValue,
    body: *const MValue,
    class_id: i32,
    out: *mut MValue,
) {
    let m = unsafe { mv_to_string(&*method) };
    let u = unsafe { mv_to_string(&*url) };
    let b = unsafe {
        if (*body).tag == TAG_STRING {
            Some(mv_to_string(&*body))
        } else {
            None
        }
    };
    let (status, resp_body) = http_do_request(&m, &u, b);
    let o = marina_object_new(class_id, 2);
    set_object_field(o, 0, mv_int(status));
    set_object_field(o, 1, mv_str_owned(resp_body));
    out_mv(
        out,
        MValue { tag: TAG_OBJECT, pad: 0, i: 0, f: 0.0, p: o },
    );
}

/// Read one HTTP request from a connection: request line + headers + body.
fn read_http_request(conn: &mut TcpStream) -> Option<(String, String, String)> {
    let _ = conn.set_read_timeout(Some(Duration::from_secs(30)));
    let mut buf = Vec::new();
    let mut one = [0u8; 1];
    loop {
        match conn.read(&mut one) {
            Ok(0) => return None,
            Ok(_) => buf.push(one[0]),
            Err(_) => return None,
        }
        if buf.ends_with(b"\r\n\r\n") {
            break;
        }
        if buf.len() > 64 * 1024 {
            return None;
        }
    }
    let head = String::from_utf8_lossy(&buf).into_owned();
    let mut lines = head.split("\r\n");
    let reqline = lines.next().unwrap_or("");
    let mut parts = reqline.split_whitespace();
    let method = parts.next().unwrap_or("").to_string();
    let path = parts.next().unwrap_or("/").to_string();
    let mut content_len = 0usize;
    for line in lines {
        if let Some(v) = line.to_lowercase().strip_prefix("content-length:") {
            content_len = v.trim().parse().unwrap_or(0);
        }
    }
    if content_len > 16 * 1024 * 1024 {
        return None;
    }
    let mut body = vec![0u8; content_len];
    if !body.is_empty() {
        conn.read_exact(&mut body).ok()?;
    }
    Some((method, path, String::from_utf8_lossy(&body).into_owned()))
}

/// `http.listen(port, handler)` — start the HTTP server. The handler runs
/// once per request (connections are handled sequentially on the listener
/// thread). The program keeps running until stopped (Ctrl-C).
#[no_mangle]
pub extern "C" fn marina_http_listen(
    port: *const MValue,
    cb: *const c_void,
    env: *mut c_void,
    env_drop: *const c_void,
    req_class_id: i32,
    res_class_id: i32,
) {
    let port_n = unsafe { (*port).i as u16 };
    let f: ListenCb = unsafe { std::mem::transmute(cb) };
    // env_drop is intentionally never called: the closure (its captures)
    // lives as long as the server does.
    let _ = env_drop;

    rt().0.lock().unwrap().pending_listeners += 1;
    struct ListenJob {
        env: *mut c_void,
        f: ListenCb,
        port_n: u16,
        req_class_id: i32,
        res_class_id: i32,
    }
    unsafe impl Send for ListenJob {}
    let job = ListenJob { env, f, port_n, req_class_id, res_class_id };
    std::thread::spawn(move || {
        let job = job;
        let ListenJob { env, f, port_n, req_class_id, res_class_id } = job;
        let listener =
            match TcpListener::bind(("0.0.0.0", port_n)) {
                Ok(l) => l,
                Err(e) => rt_panic(format!("http: cannot listen on port {} ({})", port_n, e)),
            };
        loop {
            let mut conn = match listener.accept() {
                Ok((c, _)) => c,
                Err(_) => continue,
            };
            let (method, path, body) = match read_http_request(&mut conn) {
                Some(r) => r,
                None => continue,
            };
            // request object { method, path, body }
            let req_o = marina_object_new(req_class_id, 3);
            set_object_field(req_o, 0, mv_str_owned(method));
            set_object_field(req_o, 1, mv_str_owned(path));
            set_object_field(req_o, 2, mv_str_owned(body));
            let req_mv = MValue { tag: TAG_OBJECT, pad: 0, i: 0, f: 0.0, p: req_o };
            // response object (no fields; send/json write to the socket)
            let res_o = marina_object_new(res_class_id, 0);
            let res_mv = MValue { tag: TAG_OBJECT, pad: 0, i: 0, f: 0.0, p: res_o };
            if let Ok(clone) = conn.try_clone() {
                res_sockets().lock().unwrap().insert(res_o as usize, clone);
            }
            // ownership: both objects are handed to the handler with rc 1;
            // the compiled handler releases them when it returns.
            f(env, &req_mv, &res_mv);
            res_sockets().lock().unwrap().remove(&(res_o as usize));
            drop(conn);
        }
    });
}

fn http_respond(res: *mut c_void, value: *const MValue, json: bool) {
    let stream = res_sockets()
        .lock()
        .unwrap()
        .remove(&(res as usize))
        .and_then(|s| s.try_clone().ok());
    let mut stream = match stream {
        Some(s) => s,
        None => {
            // no socket behind this response (e.g. called outside a handler):
            // fall back to printing
            unsafe { eprintln!("{}", value_to_string(&*value)) };
            return;
        }
    };
    let (ctype, payload) = if json {
        ("application/json", json_value(unsafe { &*value }))
    } else {
        ("text/plain", value_to_string(unsafe { &*value }))
    };
    let resp = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: {}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        ctype,
        payload.len(),
        payload
    );
    let _ = stream.write_all(resp.as_bytes());
}

/// `res.send(value)` — plain-text response.
#[no_mangle]
pub extern "C" fn marina_http_res_send(res: *mut c_void, value: *const MValue) {
    http_respond(res, value, false);
}

/// `res.json(value)` — JSON response (arrays, objects, strings, numbers).
#[no_mangle]
pub extern "C" fn marina_http_res_json(res: *mut c_void, value: *const MValue) {
    http_respond(res, value, true);
}

// --- JSON serialization (for res.json) ---

fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn json_value(v: &MValue) -> String {
    match v.tag {
        TAG_STRING => json_escape(&unsafe {
            String::from_utf8_lossy(str_data(v.p as *mut u8))
        }),
        TAG_INT => format!("{}", v.i as i32),
        TAG_FLOAT => fmt_float(v.f),
        TAG_BOOL => if v.i != 0 { "true".into() } else { "false".into() },
        TAG_ARRAY => {
            let arr = unsafe { &*(v.p as *mut ArrayObj) };
            let parts: Vec<String> = arr.data.iter().map(json_value).collect();
            format!("[{}]", parts.join(","))
        }
        TAG_OBJECT => {
            let obj = unsafe { &*(v.p as *mut ObjectObj) };
            let reg = class_table().lock().unwrap();
            let fields: Vec<String> = match reg.get(&obj.class_id) {
                Some(ci) => obj
                    .data
                    .iter()
                    .enumerate()
                    .map(|(i, f)| {
                        let name = ci.fields.get(i).cloned().unwrap_or_else(|| "?".into());
                        format!("{}:{}", json_escape(&name), json_value(f))
                    })
                    .collect(),
                None => Vec::new(),
            };
            format!("{{{}}}", fields.join(","))
        }
        _ => "null".into(),
    }
}
// ---------------------------------------------------------------------------
// std module: http — express-style objects (Server / Router / JsonValidator)
// ---------------------------------------------------------------------------

/// One field validator spec (`http.JsonValidator.string().required().min(n)…`).
#[derive(Clone)]
struct FieldSpec {
    /// 0 = string, 1 = number
    kind: u8,
    required: bool,
    min: Option<i64>,
    max: Option<i64>,
}

/// router object ptr -> path prefix
fn http_routers() -> &'static Mutex<HashMap<usize, String>> {
    static T: OnceLock<Mutex<HashMap<usize, String>>> = OnceLock::new();
    T.get_or_init(|| Mutex::new(HashMap::new()))
}

/// A registered route handler.
#[derive(Clone)]
struct HttpRoute {
    method: String,
    /// full matched path (prefix + route path; prefix itself for "/")
    exact: String,
    /// router prefix (also matched for "/" routes, express-style)
    prefix: String,
    f: ListenCb,
    env: *mut c_void,
}

unsafe impl Send for HttpRoute {}

fn http_routes() -> &'static Mutex<Vec<HttpRoute>> {
    static T: OnceLock<Mutex<Vec<HttpRoute>>> = OnceLock::new();
    T.get_or_init(|| Mutex::new(Vec::new()))
}

/// field-validator object ptr -> spec
fn http_field_specs() -> &'static Mutex<HashMap<usize, FieldSpec>> {
    static T: OnceLock<Mutex<HashMap<usize, FieldSpec>>> = OnceLock::new();
    T.get_or_init(|| Mutex::new(HashMap::new()))
}

/// JsonValidator object ptr -> ordered (field name, spec)
fn http_validator_specs() -> &'static Mutex<HashMap<usize, Vec<(String, FieldSpec)>>> {
    static T: OnceLock<Mutex<HashMap<usize, Vec<(String, FieldSpec)>>>> = OnceLock::new();
    T.get_or_init(|| Mutex::new(HashMap::new()))
}

/// `server.router({ path: "/x" })` — bind the router object to a prefix.
#[no_mangle]
pub extern "C" fn marina_http_router_bind(router: *const MValue, path: *const MValue) {
    let prefix = unsafe { mv_to_string(&*path) };
    let rp = unsafe { (*router).p } as usize;
    http_routers().lock().unwrap().insert(rp, prefix);
}

/// `router.get(path, handler)` / `router.post(path, handler)`.
#[no_mangle]
pub extern "C" fn marina_http_route_add(
    router: *const MValue,
    method: *const MValue,
    path: *const MValue,
    f: ListenCb,
    env: *mut c_void,
    _env_drop: *const c_void,
) {
    let rp = unsafe { (*router).p } as usize;
    let prefix = http_routers()
        .lock()
        .unwrap()
        .get(&rp)
        .cloned()
        .unwrap_or_default();
    let m = unsafe { mv_to_string(&*method) };
    let p = unsafe { mv_to_string(&*path) };
    let exact = if p == "/" { prefix.clone() } else { format!("{}{}", prefix, p) };
    http_routes().lock().unwrap().push(HttpRoute { method: m, exact, prefix, f, env });
}

/// `await server.listen(host, port)` — bind and start the accept loop.
/// Resolves the awaited promise once the listener is bound.
#[no_mangle]
pub extern "C" fn marina_http_server_listen(
    host: *const MValue,
    port: *const MValue,
    promise: *mut c_void,
    req_class_id: i32,
    res_class_id: i32,
) {
    let host_s = unsafe { mv_to_string(&*host) };
    let port_n = unsafe { (*port).i } as u16;
    struct ListenJob {
        host_s: String,
        port_n: u16,
        promise: *mut c_void,
        req_class_id: i32,
        res_class_id: i32,
    }
    unsafe impl Send for ListenJob {}
    let job = ListenJob { host_s, port_n, promise, req_class_id, res_class_id };
    rt().0.lock().unwrap().pending_listeners += 1;
    std::thread::spawn(move || {
        let job = job;
        let ListenJob { host_s, port_n, promise, req_class_id, res_class_id } = job;
        let listener = match TcpListener::bind((host_s.as_str(), port_n)) {
            Ok(l) => l,
            Err(e) => rt_panic(format!("http: cannot listen on {}:{} ({})", host_s, port_n, e)),
        };
        // bound successfully: resume the awaiting main function
        marina_promise_resolve(promise, &MValue::default());

        for stream in listener.incoming() {
            let Ok(mut stream) = stream else { continue };
            let (method, path, body) = match read_http_request(&mut stream) {
                Some(r) => r,
                None => continue,
            };
            let route = http_routes()
                .lock()
                .unwrap()
                .iter()
                .find(|r| {
                    r.method == method
                        && (path == r.exact || (path == r.prefix && r.exact == r.prefix))
                })
                .cloned();
            let Some(route) = route else {
                let resp = "HTTP/1.1 404 Not Found\r\nContent-Type: text/plain\r\nContent-Length: 9\r\nConnection: close\r\n\r\nnot found";
                let _ = stream.write_all(resp.as_bytes());
                continue;
            };
            // req object: { method, path, body }
            let req = marina_object_new(req_class_id, 3);
            set_object_field(req, 0, mv_str_owned(method));
            set_object_field(req, 1, mv_str_owned(path));
            set_object_field(req, 2, mv_str_owned(body));
            // res object backed by this connection
            let res = marina_object_new(res_class_id, 0);
            match stream.try_clone() {
                Ok(sock) => {
                    res_sockets().lock().unwrap().insert(res as usize, sock);
                }
                Err(_) => continue,
            }
            let req_mv = MValue { tag: TAG_OBJECT, pad: 0, i: 0, f: 0.0, p: req };
            let res_mv = MValue { tag: TAG_OBJECT, pad: 0, i: 0, f: 0.0, p: res };
            // ownership: both objects are handed to the handler with rc 1;
            // the compiled handler releases them when it returns.
            (route.f)(route.env, &req_mv, &res_mv);
            // handler never responded -> 404
            if res_sockets().lock().unwrap().remove(&(res as usize)).is_some() {
                let resp = "HTTP/1.1 404 Not Found\r\nContent-Type: text/plain\r\nContent-Length: 9\r\nConnection: close\r\n\r\nnot found";
                let _ = stream.write_all(resp.as_bytes());
            }
        }
    });
}

/// `http.JsonValidator.string()` / `.number()` — a fresh chainable validator.
#[no_mangle]
pub extern "C" fn marina_http_field_init(field_obj: *mut c_void, kind: i32) {
    http_field_specs().lock().unwrap().insert(
        field_obj as usize,
        FieldSpec { kind: kind as u8, required: false, min: None, max: None },
    );
}

/// `.required()` / `.min(n)` / `.max(n)` — mutate the validator spec.
#[no_mangle]
pub extern "C" fn marina_http_field_op(field_obj: *mut c_void, op: i32, arg: *const MValue) {
    let mut g = http_field_specs().lock().unwrap();
    if let Some(spec) = g.get_mut(&(field_obj as usize)) {
        match op {
            0 => spec.required = true,
            1 => spec.min = Some(unsafe { (*arg).i }),
            2 => spec.max = Some(unsafe { (*arg).i }),
            _ => {}
        }
    }
}

/// `new http.JsonValidator({ field: <field validator>, ... })` — snapshot the
/// schema (ordered field name + spec) into the validator object.
#[no_mangle]
pub extern "C" fn marina_http_validator_init(v: *mut c_void, schema: *const MValue) {
    let sp = unsafe { (*schema).p } as *mut c_void;
    let mut specs = Vec::new();
    unsafe {
        let obj = as_object(sp);
        let class_id = (*obj).class_id;
        let names = class_table()
            .lock()
            .unwrap()
            .get(&class_id)
            .map(|c| c.fields.clone())
            .unwrap_or_default();
        for (i, name) in names.iter().enumerate() {
            let mut mv = MValue::default();
            marina_object_get(sp, i as i64, &mut mv);
            let fptr = if is_ptr_tag(mv.tag) { mv.p as usize } else { 0 };
            let spec = http_field_specs()
                .lock()
                .unwrap()
                .get(&fptr)
                .cloned()
                .unwrap_or(FieldSpec { kind: 0, required: false, min: None, max: None });
            drop_mv(&mv);
            specs.push((name.clone(), spec));
        }
    }
    http_validator_specs().lock().unwrap().insert(v as usize, specs);
}

/// `validator.validate(body)` — parse + check a JSON object body; returns an
/// object of the checker-synthesized result class (`out_class`).
#[no_mangle]
pub extern "C" fn marina_http_validate(
    v: *mut c_void,
    body: *const MValue,
    out_class: i32,
    out: *mut MValue,
) {
    let vp = v as usize;
    let specs = http_validator_specs().lock().unwrap().get(&vp).cloned();
    let Some(specs) = specs else {
        rt_panic("validate called on an invalid validator object".to_string());
    };
    let body_s = unsafe { mv_to_string(&*body) };
    let fields = match json_parse(&body_s) {
        Some(JVal::Obj(m)) => m,
        Some(_) => rt_panic("http: request body must be a JSON object".to_string()),
        None => rt_panic("http: invalid JSON body".to_string()),
    };
    let obj = marina_object_new(out_class, specs.len() as i64);
    for (i, (name, spec)) in specs.iter().enumerate() {
        let val = fields.iter().find(|(k, _)| k == name).map(|(_, v)| v);
        let Some(jv) = val else {
            if spec.required {
                rt_panic(format!("http: missing required field '{}'", name));
            }
            continue;
        };
        let mv = match (spec.kind, jv) {
            (0, JVal::Str(s)) => {
                let len = s.chars().count() as i64;
                if let Some(mn) = spec.min {
                    if len < mn {
                        rt_panic(format!(
                            "http: field '{}' must be at least {} characters",
                            name, mn
                        ));
                    }
                }
                if let Some(mx) = spec.max {
                    if len > mx {
                        rt_panic(format!(
                            "http: field '{}' must be at most {} characters",
                            name, mx
                        ));
                    }
                }
                mv_str_owned(s.clone())
            }
            (1, JVal::Num(x)) => mv_int(*x as i64),
            _ => rt_panic(format!("http: field '{}' has the wrong type", name)),
        };
        set_object_field(obj, i as i64, mv);
    }
    out_mv(
        out,
        MValue { tag: TAG_OBJECT, pad: 0, i: 0, f: 0.0, p: obj },
    );
}

// --- minimal JSON parser (for JsonValidator.validate) ---

#[allow(dead_code)]
enum JVal {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<JVal>),
    Obj(Vec<(String, JVal)>),
}

struct JsonParser<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> JsonParser<'a> {
    fn skip_ws(&mut self) {
        while self.i < self.b.len() && (self.b[self.i] as char).is_ascii_whitespace() {
            self.i += 1;
        }
    }
    fn peek(&self) -> Option<u8> {
        self.b.get(self.i).copied()
    }
    fn eat(&mut self, c: u8) -> bool {
        if self.peek() == Some(c) {
            self.i += 1;
            true
        } else {
            false
        }
    }
    fn value(&mut self) -> Option<JVal> {
        self.skip_ws();
        match self.peek()? {
            b'{' => self.object(),
            b'[' => self.array(),
            b'"' => self.string().map(JVal::Str),
            b't' => self.lit("true").map(|_| JVal::Bool(true)),
            b'f' => self.lit("false").map(|_| JVal::Bool(false)),
            b'n' => self.lit("null").map(|_| JVal::Null),
            _ => self.number(),
        }
    }
    fn lit(&mut self, word: &str) -> Option<()> {
        if self.b[self.i..].starts_with(word.as_bytes()) {
            self.i += word.len();
            Some(())
        } else {
            None
        }
    }
    fn string(&mut self) -> Option<String> {
        if !self.eat(b'"') {
            return None;
        }
        let mut out = Vec::new();
        loop {
            let c = self.peek()?;
            self.i += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    let e = self.peek()?;
                    self.i += 1;
                    match e {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'u' => {
                            if self.i + 4 > self.b.len() {
                                return None;
                            }
                            let hex = std::str::from_utf8(&self.b[self.i..self.i + 4]).ok()?;
                            let n = u32::from_str_radix(hex, 16).ok()?;
                            self.i += 4;
                            let ch = char::from_u32(n).unwrap_or('\u{fffd}');
                            let mut buf = [0; 4];
                            out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        }
                        _ => return None,
                    }
                }
                _ => out.push(c),
            }
        }
        Some(String::from_utf8_lossy(&out).into_owned())
    }
    fn number(&mut self) -> Option<JVal> {
        let start = self.i;
        if self.eat(b'-') {}
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == b'.' || c == b'e' || c == b'E' || c == b'+' || c == b'-' {
                self.i += 1;
            } else {
                break;
            }
        }
        if start == self.i {
            return None;
        }
        let s = std::str::from_utf8(&self.b[start..self.i]).ok()?;
        s.parse::<f64>().ok().map(JVal::Num)
    }
    fn array(&mut self) -> Option<JVal> {
        if !self.eat(b'[') {
            return None;
        }
        let mut out = Vec::new();
        self.skip_ws();
        if self.eat(b']') {
            return Some(JVal::Arr(out));
        }
        loop {
            out.push(self.value()?);
            self.skip_ws();
            if self.eat(b']') {
                break;
            }
            if !self.eat(b',') {
                return None;
            }
        }
        Some(JVal::Arr(out))
    }
    fn object(&mut self) -> Option<JVal> {
        if !self.eat(b'{') {
            return None;
        }
        let mut out = Vec::new();
        self.skip_ws();
        if self.eat(b'}') {
            return Some(JVal::Obj(out));
        }
        loop {
            self.skip_ws();
            let key = self.string()?;
            self.skip_ws();
            if !self.eat(b':') {
                return None;
            }
            let val = self.value()?;
            out.push((key, val));
            self.skip_ws();
            if self.eat(b'}') {
                break;
            }
            if !self.eat(b',') {
                return None;
            }
        }
        Some(JVal::Obj(out))
    }
}

fn json_parse(s: &str) -> Option<JVal> {
    let mut p = JsonParser { b: s.as_bytes(), i: 0 };
    let v = p.value()?;
    p.skip_ws();
    if p.i != p.b.len() {
        return None;
    }
    Some(v)
}